import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_write_TriageGen0Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;
    private static final int RECORD_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        // Use a fixed record size for predictable testing of assembly logic
        tarOut = new TarArchiveOutputStream(out, RECORD_SIZE, RECORD_SIZE);
    }





    @Test
    public void testWrite_PartialWritesAssemblingToRecord() throws IOException {
        int totalSize = RECORD_SIZE;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(totalSize);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[totalSize];
        for (int i = 0; i < totalSize; i++) data[i] = (byte) i;

        // Write in small chunks to trigger the assemLen logic
        int chunkSize = 100;
        int written = 0;
        while (written < totalSize) {
            tarOut.write(data, written, chunkSize);
            written += chunkSize;
        }
        tarOut.closeArchiveEntry();

        Assert.assertTrue(out.size() > 0);
    }








}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_write_TriageGen0Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;
    private static final int RECORD_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        // Use a fixed record size for predictable testing of assembly logic
        tarOut = new TarArchiveOutputStream(out, RECORD_SIZE, RECORD_SIZE);
    }







    @Test
    public void testWrite_LargeWriteTriggeringAssemblyAndDirectWrite() throws IOException {
        // Test scenario where assemLen > 0 and (assemLen + numToWrite) >= recordBuf.length
        // This covers the System.arraycopy branches for assembling a record
        int totalSize = RECORD_SIZE * 2;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(totalSize);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[totalSize];
        for (int i = 0; i < totalSize; i++) data[i] = (byte) (i % 128);

        // 1. Write a small chunk to set assemLen > 0
        tarOut.write(data, 0, 100);

        // 2. Write a chunk that causes (assemLen + numToWrite) >= recordBuf.length
        // assemLen is 100. We need to write at least 412 more to hit 512.
        tarOut.write(data, 100, 450);

        // 3. Write the remainder
        tarOut.write(data, 550, totalSize - 550);

        tarOut.closeArchiveEntry();
        Assert.assertTrue(out.size() > 0);
    }






}

