public class TarArchiveOutputStream_write_TriageGen0Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;
    private static final int RECORD_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        // Use a fixed record size for predictable testing of assembly logic
        tarOut = new TarArchiveOutputStream(out, RECORD_SIZE, RECORD_SIZE);
    }













    @Test
    public void testWrite_AssembleSmallThenLoopRemaining() throws IOException {
        // Test path: assemLen > 0 (small chunk), then numToWrite > 0 (large chunk)
        int totalSize = RECORD_SIZE + 10;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(totalSize);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[totalSize];

        // 1. Fill assemBuf partially
        tarOut.write(data, 0, 50); 
        // 2. Write a large chunk that goes through the while loop
        tarOut.write(data, 50, totalSize - 50);

        tarOut.closeArchiveEntry();
        Assert.assertTrue(out.size() > 0);
    }
